                const upright=!tilted||tilted.size<start?placer.search(unionE(list),[...blocked,...others,...placedInks],[n],false,options):null;
                placed=tilted&&!(upright&&upright.size>tilted.size)?tilted:upright;
                if(placed){anchor=k;break;}
              }
              if(!placed){undo();placedInks.splice(placedInks.length-done.length+1);return null;}
              Object.assign(n.style,{fontSize:`${placed.size}px`,lineHeight:`${placed.lh}px`,width:`${placed.width}px`,
                height:`${Math.ceil(placed.lh*3)}px`,textAlign:'center'});
              n.style.left=`${parseFloat(n.style.left)+placed.moves[0].dx}px`;n.style.top=`${parseFloat(n.style.top)+placed.moves[0].dy}px`;
              aidokuTurnGloss(n,placed);
              Object.assign(n.style,{color:`rgb(${fill.join(',')})`,webkitTextStrokeWidth:`${Math.max(placed.texture?2.5:0,strokeWidth(placed.size))}px`,
                webkitTextStrokeColor:`rgb(${outline.join(',')})`,paintOrder:'stroke fill'});
              Object.assign(n.dataset,{sourceBackgroundColor:'source-effect-gloss',sourceAppliedBackgroundRGB:'',
                sourceAppliedTextRGB:fill.join(','),sourceAppliedStrokeRGB:outline.join(','),sourceTextOutline:'true',sourceStrokeColor:'gloss'});
              const ink=inkE(n);placedInks.push({left:ink.left-3,top:ink.top-3,right:ink.right+3,bottom:ink.bottom+3});
