            .map(other=>rectE(other.sourceBounds));
          const notes=new Set(done.map(d=>d.node));
          for(const c of unit){
            for(const plate of platesOf(c.id,c.node))plate.remove();
            for(const layer of [restoredPanelGeometry.get(c.item)?.canvas,slantedSourcePanels.get(c.item)?.canvas,
              ...Array.from(root.children).filter(layer=>layer.dataset.aidokuRegion===c.id&&layer.dataset.aidokuImageOcrOverlay!=='item')])
              if(layer?.parentElement)layer.remove();
