              for(const cut of painted){pieces=aidokuSubtractRects(pieces,cut);if(pieces.length>64)break;}
              effectZones.push(...pieces.filter(q=>q.right-q.left>=.5&&q.bottom-q.top>=.5).map(q=>({...q,id:c.id})));
            }
            if(!notes.has(c.node)){c.node.textContent='';c.node.style.visibility='hidden';c.node.dataset.effectGlossJoined=lead.id;}
            c.node.dataset.sourceErasurePreserved='effect-gloss';delete c.node.dataset.effectGlossReject;
          }
          for(const d of done){
            sides[d.placed.side]=(sides[d.placed.side]||0)+1;
            d.node.dataset.effectGloss=JSON.stringify({role:lead.role,size:d.placed.size,side:d.placed.side,gap:d.placed.gap,texture:d.placed.texture,
              angle:Math.round((d.placed.angle||0)*1800/Math.PI)/10,source:Math.round(rawAngle*1800/Math.PI)/10,
              ...(d.placed.center?{block:[...d.placed.center,...d.placed.block].map(v=>Math.round(v*10)/10)}:{}),
              rank:d.placed.rank,edge:Math.round(d.placed.edge*1000)/1000,members:d.list.map(c=>c.id),unit:unit.map(c=>c.id),
              notes:done.length,anchor:d.anchor,cover:d.list.map(c=>Math.round(c.cover.share*100)/100),ms:Math.round(performance.now()-started)});
          }
