        }})();
        probe.width=0;probe.height=0;
        root.dataset.effectGlosses=String(glossed);root.dataset.effectGlossRejected=String(rejected);root.dataset.effectGlossSides=JSON.stringify(sides);
        root.dataset.effectGlossMilliseconds=String(Math.round((performance.now()-effectStarted)*10)/10);
