    // translated only where their source erases cleanly. One that ended on a plate covering artwork (plate pixels
    // outside its source box whose page colour differs from the plate, the harm measure) keeps its source instead:
    // its caption and plates are removed and its box becomes kept lettering, so the page shows it as printed.
    (()=>{
      // Share of the plate area: 2 % (a few clipped hair tips or a frame corner) already keeps the source.
      const recoveredLineHarmLimit=.02;
      const recovered=items.filter(item=>item?.recoveredLine===true);
      if(!recovered.length||opacity!==1||!coverSource?.complete||!(coverSource.naturalWidth>0)||!cleanupImageGeometry)return;
      try {
        const started=performance.now(),f=cleanupImageGeometry.frame,iw=coverSource.naturalWidth,ih=coverSource.naturalHeight;
        if(!Array.isArray(f)||f.length!==4||!f.every(Number.isFinite)||!(f[2]>0&&f[3]>0))return;
        const canvasR=document.createElement('canvas'),contextR=canvasR.getContext('2d',{willReadFrequently:true});
        const plateKinds=new Set(['source-readability-panel','source-readability-backing','source-rotated-panel']);
        const shown=layer=>layer.style.visibility!=='hidden'&&getComputedStyle(layer).display!=='none';
        const colourOf=text=>{const v=String(text||'').match(/[0-9.]+/g)?.map(Number);
          return v&&v.length>=3&&(v.length<4||v[3]>0)?v.slice(0,3):null;};
        const dropped=[],shares={};let budget=262144;
        (()=>{for(const item of recovered){
          const id=String(item.id),b=item.sourceBounds;
          if(!Array.isArray(b)||b.length!==4||!b.every(Number.isFinite))continue;
          const node=Array.from(root.querySelectorAll('[data-aidoku-image-ocr-overlay="item"]')).find(n=>n.dataset.aidokuRegion===id);
          if(!node)continue;
          const plates=Array.from(root.children).filter(layer=>plateKinds.has(layer.dataset.aidokuImageOcrOverlay)&&
            layer.dataset.aidokuRegion===id&&shown(layer));
          if(node.dataset.sourceBackgroundColor==='rotated-panel'&&shown(node))plates.push(node);
          let harm=0,total=0;
          for(const plate of plates){
            const colour=colourOf(getComputedStyle(plate).backgroundColor)||colourOf(node.dataset.sourceAppliedBackgroundRGB);
            if(!colour)continue;
            const r=plate.getBoundingClientRect();
            const x0=Math.max(0,Math.floor((r.left-f[0])/f[2]*iw)),y0=Math.max(0,Math.floor((r.top-f[1])/f[3]*ih));
            const x1=Math.min(iw,Math.ceil((r.right-f[0])/f[2]*iw)),y1=Math.min(ih,Math.ceil((r.bottom-f[1])/f[3]*ih));
            const sw=x1-x0,sh=y1-y0;
            if(sw<2||sh<2)continue;
            const k=Math.min(1,Math.sqrt(32768/(sw*sh))),w=Math.max(1,Math.round(sw*k)),h=Math.max(1,Math.round(sh*k));
            if(w*h>budget)continue;
            budget-=w*h;
            canvasR.width=w;canvasR.height=h;contextR.drawImage(coverSource,x0,y0,sw,sh,0,0,w,h);
            const rgba=contextR.getImageData(0,0,w,h).data;
            // The source box (plus 2 image pixels) is meant to be covered.
            const bx0=(b[0]*iw-2-x0)*k,by0=(b[1]*ih-2-y0)*k,bx1=((b[0]+b[2])*iw+2-x0)*k,by1=((b[1]+b[3])*ih+2-y0)*k;
            for(let y=0,p=0;y<h;y++)for(let x=0;x<w;x++,p+=4){
              total++;
              if(x+.5>=bx0&&x+.5<bx1&&y+.5>=by0&&y+.5<by1)continue;
              if(Math.max(Math.abs(rgba[p]-colour[0]),Math.abs(rgba[p+1]-colour[1]),Math.abs(rgba[p+2]-colour[2]))>40)harm++;
            }
          }
          const share=total?harm/total:0;
          shares[id]=plates.length?Math.round(share*1000)/1000:null;
          if(!(share>=recoveredLineHarmLimit))continue;
          for(const plate of plates)if(plate!==node)plate.remove();
          node.remove();
          dropped.push(item);
        }})();
        canvasR.width=0;canvasR.height=0;
        if(dropped.length){
          // The dropped boxes stay as printed: kept lettering restores the page image above any erasure there,
          // except where a painted caption's own source box meets them.
          const droppedIDs=new Set(dropped.map(item=>String(item.id)));
          const painted=items.filter(item=>!droppedIDs.has(String(item.id))).flatMap(item=>{
            const b=item.sourceBounds;
            return Array.isArray(b)&&b.length===4&&b.every(Number.isFinite)?[[f[0]+b[0]*f[2],f[1]+b[1]*f[3],b[2]*f[2],b[3]*f[3]]]:[];
          });
          const kept=dropped.map(item=>{const b=item.sourceBounds;
            return {id:String(item.id),keptLettering:true,x:f[0]+b[0]*f[2],y:f[1]+b[1]*f[3],width:b[2]*f[2],height:b[3]*f[3],
              sourceFontSize:Number(item.sourceFontSize)>0?Number(item.sourceFontSize):null};});
          keptItems.push(...kept);keptZones.push(...aidokuKeptLetteringZones(kept,painted));
        }
        root.dataset.recoveredLines=JSON.stringify(shares);
        root.dataset.recoveredLinesDropped=String(dropped.length);
        root.dataset.recoveredLinesMilliseconds=String(Math.round((performance.now()-started)*10)/10);
      } catch(error) {root.dataset.recoveredLinesError=String(error).slice(0,160);}
    })();
    // Kept source lettering is never covered. Where a plate, backing, glyph
    // cover, erasure or restoration layer reaches into a kept zone, the page
    // image itself is shown again above it: one clipped copy of the source
    // <img> (same resource and scaling, so the pixels are identical). The
    // translated glyphs are cut out of that copy and stay visible; a line that
    // still meets kept lettering is counted, never hidden.
    if((keptZones.length||effectZones.length)&&sourceImage&&cleanupImageGeometry&&opacity===1){
      try {
        const keptStarted=performance.now(),image=sourceImage.getBoundingClientRect();
        const box=r=>({left:r.left,top:r.top,right:r.right,bottom:r.bottom});
        const meets=(a,b)=>Math.min(a.right,b.right)-Math.max(a.left,b.left)>.25&&Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top)>.25;
        const nodes=Array.from(root.querySelectorAll('[data-aidoku-image-ocr-overlay="item"]'))
          .filter(node=>node.style.visibility!=='hidden'&&getComputedStyle(node).display!=='none');
        const glyphLines=[];
        (()=>{for(const node of nodes){
          const range=document.createRange();range.selectNodeContents(node);
          for(const r of range.getClientRects())if(r.width>0&&r.height>0)
            glyphLines.push({left:r.left-1.5,top:r.top-1.5,right:r.right+1.5,bottom:r.bottom+1.5});
        }})();
        const covers=Array.from(root.children).filter(layer=>{
          if(layer.style.visibility==='hidden')return false;
          const style=getComputedStyle(layer);
          if(style.display==='none')return false;
          if(layer.dataset.aidokuImageOcrOverlay!=='item')return true;
          return layer.childElementCount>0||!/^rgba[(][^,)]*,[^,)]*,[^,)]*,\\s*0(?:[.]0*)?[)]$|^transparent$/u.test(style.backgroundColor)||style.backgroundImage!=='none';
        }).map(layer=>box(layer.getBoundingClientRect())).filter(r=>r.right>r.left&&r.bottom>r.top);
        const area=(a,b)=>Math.max(0,Math.min(a.right,b.right)-Math.max(a.left,b.left))*
          Math.max(0,Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top));
        // A caption set across the kept lettering (a placement collision, over
        // a tenth of its box) keeps its plate: showing the lettering in pieces
        // around the translated lines would read as neither.
        const collided=new Set(keptItems.filter(k=>{
          const zones=keptZones.filter(z=>z.id===k.id);
          return glyphLines.reduce((sum,g)=>sum+zones.reduce((n,z)=>n+area(g,z),0),0)>.1*k.width*k.height;
        }).map(k=>k.id));
        // Effect lettering kept with a gloss (see effectZones) is always shown again.
        const zones=[...keptZones.filter(z=>!collided.has(z.id)&&covers.some(c=>meets(c,z))),...effectZones];
        let pieces=zones.map(box);
        (()=>{for(const g of glyphLines)if(zones.some(z=>meets(g,z)))pieces=aidokuSubtractRects(pieces,g);})();
        pieces=pieces.map(p=>({left:Math.max(p.left,image.left),top:Math.max(p.top,image.top),
          right:Math.min(p.right,image.right),bottom:Math.min(p.bottom,image.bottom)}))
          .filter(p=>p.right-p.left>=.5&&p.bottom-p.top>=.5);
        const overlaps=new Set([...collided,...zones.filter(z=>glyphLines.some(g=>meets(g,z))).map(z=>z.id)]);
        if(pieces.length&&pieces.length<=1024&&image.width>0&&image.height>0){
          const path=pieces.map(p=>`M ${p.left-image.left} ${p.top-image.top} H ${p.right-image.left} `+
            `V ${p.bottom-image.top} H ${p.left-image.left} Z`).join(' ');
          const copy=sourceImage.cloneNode(false);copy.removeAttribute('id');
          copy.setAttribute('data-aidoku-image-ocr-overlay','kept-lettering');copy.setAttribute('aria-hidden','true');
          copy.style.cssText=sourceImage.style.cssText;
          Object.assign(copy.style,{position:'absolute',zIndex:'4',pointerEvents:'none',margin:'0',transform:'none',
            left:`${image.left+scrollX}px`,top:`${image.top+scrollY}px`,width:`${image.width}px`,height:`${image.height}px`,
            objectFit:getComputedStyle(sourceImage).objectFit,clipPath:`path('${path}')`});
          root.appendChild(copy);
          root.dataset.keptLetteringRestored=String(new Set(zones.map(z=>z.id)).size);
        }
        root.dataset.keptLettering=String(keptItems.length);
        root.dataset.keptLetteringTextOverlaps=String(overlaps.size);
        root.dataset.keptLetteringCollisions=String(collided.size);
        root.dataset.keptLetteringMilliseconds=String(Math.round((performance.now()-keptStarted)*10)/10);
      } catch(error) {root.dataset.keptLetteringError=String(error).slice(0,160);}
    }
    if(typeof sourcePixelReader!=='undefined')sourcePixelReader?.release();
    if(typeof aidokuPixelKernels!=='undefined')aidokuPixelKernels.trim?.();
    return {
      status: 'committed', revision: String(revision),
      itemCount: renderedItemCount,
      letterFaceFailed: Boolean(letterStyleSerif && letterStyleFonts?.serif === true && !serifLetterFamily)
    };
    };
    // The face time is taken before the continuation runs (and compiles).
    return letterStyleSerif
      ? aidokuLetterFace('serif').then(family => renderWithLetterFaces(family, performance.now() - letterFaceStarted))
      : renderWithLetterFaces(null, performance.now() - letterFaceStarted);
    """
}

struct BrowserOverlayItem: Equatable, Sendable {
    /// Stable identity assigned by the temporal OCR tracker. Rendering must
    /// preserve this identity instead of treating every OCR/translation
    /// publication as a brand-new card.
    let stableRegionID: UInt64?
    let rect: CGRect
    let sourcePolygon: [CGPoint]
    let auxiliaryInkRects: [CGRect]
    let auxiliaryInkPolygons: [[CGPoint]]
    let sourceText: String
    let translatedText: String?
    let confidence: Double
    let sourceOrientation: BrowserOCRSourceOrientation
    let sourceSingleVerticalColumn: Bool?
    let translationReuseIdentity: NativeTranslationReuseIdentity?
    /// Source lettering that stays visible (see `ReaderTranslationRegion.keepsOriginalLettering`).
    /// Layout reserves its box and the overlay protects it; it is never typeset or erased.
    let keepsSourceLettering: Bool
    /// Normalized clean paper of the balloon holding only this caption (see `ReaderTranslationBalloonInterior`).
    let balloonInterior: ReaderTranslationBalloonInterior?
    /// Member OCR boxes of a joined balloon unit (image px; `rect` is their union): erasure and plate bounds.
    let unitMemberRects: [CGRect]
    /// Recovered below the OCR confidence gate (see `ReaderTranslationRegion.isRecoveredLine`).
    let recoveredLine: Bool

    init(
        stableRegionID: UInt64? = nil,
        rect: CGRect,
        sourceText: String,
        translatedText: String?,
        confidence: Double,
        sourceOrientation: BrowserOCRSourceOrientation = .unknown,
        sourceSingleVerticalColumn: Bool? = nil,
        translationReuseIdentity: NativeTranslationReuseIdentity? = nil,
        sourcePolygon: [CGPoint] = [],
        auxiliaryInkRects: [CGRect] = [],
        auxiliaryInkPolygons: [[CGPoint]] = [],
        balloonInterior: ReaderTranslationBalloonInterior? = nil,
        unitMemberRects: [CGRect] = [],
        keepsSourceLettering: Bool = false,
        recoveredLine: Bool = false
    ) {
        self.keepsSourceLettering = keepsSourceLettering
        self.recoveredLine = recoveredLine
        self.stableRegionID = stableRegionID
        self.balloonInterior = balloonInterior
        self.unitMemberRects = unitMemberRects
        self.rect = rect
        self.sourcePolygon = sourcePolygon
        self.auxiliaryInkRects = auxiliaryInkRects
        self.auxiliaryInkPolygons = auxiliaryInkPolygons
        self.sourceText = sourceText
        self.translatedText = translatedText
        self.confidence = confidence
        self.sourceOrientation = sourceOrientation
        self.sourceSingleVerticalColumn = sourceSingleVerticalColumn
        self.translationReuseIdentity = translationReuseIdentity
    }
}

/// Stable layout order is separate from the language-aware translation order.
/// An approximate comparator can form cycles (A~B, B~C, A<C); anchor rows
/// before sorting their members so publication order cannot jitter placement.
struct BrowserOverlayItemOrdering {
    static func ordered(_ items: [BrowserOverlayItem]) -> [BrowserOverlayItem] {
        var counts: [UInt64: Int] = [:]
        for item in items { if let id = item.stableRegionID { counts[id, default: 0] += 1 } }
        let valid = items.filter { item in
            let r = item.rect
            return !r.isNull && !r.isEmpty &&
                [r.minX, r.minY, r.maxX, r.maxY].allSatisfy(\.isFinite) &&
                (item.stableRegionID.map { counts[$0] == 1 } ?? true)
        }
        func tie(_ a: BrowserOverlayItem, _ b: BrowserOverlayItem) -> Bool {
            if a.rect.width != b.rect.width { return a.rect.width < b.rect.width }
            if a.rect.height != b.rect.height { return a.rect.height < b.rect.height }
            if a.stableRegionID != b.stableRegionID { return (a.stableRegionID ?? .max) < (b.stableRegionID ?? .max) }
            if a.sourceText != b.sourceText { return a.sourceText < b.sourceText }
            return (a.translatedText ?? "") < (b.translatedText ?? "")
        }
        let byY = valid.sorted {
            if $0.rect.minY != $1.rect.minY { return $0.rect.minY < $1.rect.minY }
            if $0.rect.minX != $1.rect.minX { return $0.rect.minX < $1.rect.minX }
            return tie($0, $1)
        }
        var result: [BrowserOverlayItem] = []
        var start = 0
        while start < byY.count {
            var end = start + 1
            while end < byY.count && byY[end].rect.minY <= byY[start].rect.minY + 2 { end += 1 }
            result.append(contentsOf: byY[start..<end].sorted {
                if $0.rect.minX != $1.rect.minX { return $0.rect.minX < $1.rect.minX }
                if $0.rect.minY != $1.rect.minY { return $0.rect.minY < $1.rect.minY }
                return tie($0, $1)
            })
            start = end
        }
        // Different tracker IDs may still describe the exact same painted
        // source. Collapse only exact geometry/text/orientation duplicates;
        // repeated dialogue elsewhere and competing translations remain distinct.
        struct PaintIdentity: Hashable {
            let x: CGFloat; let y: CGFloat; let width: CGFloat; let height: CGFloat
            let source: String; let translation: String?; let orientation: String
            let singleColumn: Bool?
        }
        var seen = Set<PaintIdentity>()
        return result.filter { item in
            seen.insert(PaintIdentity(x: item.rect.minX, y: item.rect.minY,
                width: item.rect.width, height: item.rect.height,
                source: item.sourceText, translation: item.translatedText,
                orientation: item.sourceOrientation.rawValue,
                singleColumn: item.sourceSingleVerticalColumn)).inserted
        }
    }
}

struct BrowserOverlayVisibility {
    static func visibleItems(
        _ items: [BrowserOverlayItem]
    ) -> [BrowserOverlayItem] {
        return items.compactMap { item in
            let sourceIsEmpty = item.sourceText.trimmingCharacters(
                in: .whitespacesAndNewlines
            ).isEmpty
            let translationIsEmpty = item.translatedText?.trimmingCharacters(
                in: .whitespacesAndNewlines
            ).isEmpty ?? true
            guard !sourceIsEmpty || !translationIsEmpty else { return nil }
            let visibleItem: BrowserOverlayItem
            if translationIsEmpty, item.translatedText != nil {
                // Treat a blank provider response as untranslated so it can
                // never create an empty replacement surface.
                visibleItem = BrowserOverlayItem(
                    stableRegionID: item.stableRegionID,
                    rect: item.rect,
                    sourceText: item.sourceText,
                    translatedText: nil,
                    confidence: item.confidence,
                    sourceOrientation: item.sourceOrientation,
                    sourceSingleVerticalColumn:
                        item.sourceSingleVerticalColumn,
                    translationReuseIdentity: item.translationReuseIdentity,
                    sourcePolygon: item.sourcePolygon, auxiliaryInkRects: item.auxiliaryInkRects, auxiliaryInkPolygons: item.auxiliaryInkPolygons,
                    balloonInterior: item.balloonInterior, unitMemberRects: item.unitMemberRects,
                    keepsSourceLettering: item.keepsSourceLettering, recoveredLine: item.recoveredLine
                )
            } else {
                visibleItem = item
            }
            return visibleItem
        }
    }
}

/// Matches the established image-overlay display boundary: line grouping is
/// owned by OCR, and presentation removes only an exact repeated string in the
/// same region.
struct BrowserImageSourceOverlayConsolidator {
    static func consolidate(
        _ input: [BrowserOverlayItem]
    ) -> [BrowserOverlayItem] {
        // Preserve the c1b89c7 display-boundary contract: OCR owns text-line
        // grouping, while the presentation boundary removes only an exact
        // repeated string occupying the same region. Geometry-only joining
        // changes the recognized sentence and made upgraded capture output
        // differ from the established renderer result.
        var unique: [BrowserOverlayItem] = []
        for item in input.sorted(by: readingOrder) {
            let normalized = normalizedText(item.sourceText)
            let duplicate = unique.contains { existing in
                normalizedText(existing.sourceText) == normalized &&
                    overlapRatio(existing.rect, item.rect) >= 0.70
            }
            if !duplicate { unique.append(item) }
        }
        return unique
    }

    private static func normalizedText(_ text: String) -> String {
        text.trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
    }

    private static func overlapRatio(_ left: CGRect, _ right: CGRect) -> CGFloat {
        let intersection = left.intersection(right)
        guard !intersection.isNull else { return 0 }
        let smallerArea = min(
            left.width * left.height,
            right.width * right.height
        )
        guard smallerArea > 0 else { return 0 }
        return intersection.width * intersection.height / smallerArea
    }

    private static func readingOrder(
        _ left: BrowserOverlayItem,
        _ right: BrowserOverlayItem
    ) -> Bool {
        if abs(left.rect.minY - right.rect.minY) > 2 {
            return left.rect.minY < right.rect.minY
        }
        return left.rect.minX < right.rect.minX
    }
}

